// Central error handler: makes failed runs visible instead of
// failing silently. Swap the mock log for email/Slack paging.
const e = $input.first().json;
const summary = {
  workflow: e.workflow?.name,
  node: e.execution?.lastNodeExecuted,
  error: e.execution?.error?.message,
  url: e.execution?.url,
  at: new Date().toISOString(),
};
console.log('[lendloop][ERROR]', JSON.stringify(summary));
return [{ json: { alerted: true, ...summary } }];
